  }
  // If primary - do nothing, user stays
} catch (error) {
  // handle error
}
```

h2-replace-one-subscription-with-another.translation:
```typescript showLineNumbers
import { Capacitor } from '@capacitor/core';
import { createFlowView } from '@adapty/capacitor';
import type { MakePurchaseParamsInput } from '@adapty/capacitor';

const productPurchaseParams = flow.paywalls
  .flatMap((paywall) => paywall.productIdentifiers)
  .map((productId) => {
    const params: MakePurchaseParamsInput = {};
    if (Capacitor.getPlatform() === 'android') {
      params.android = {
        subscriptionUpdateParams: {
          oldSubVendorProductId: 'PRODUCT_ID_OF_THE_CURRENT_ACTIVE_SUBSCRIPTION',
          prorationMode: 'with_time_proration',
        },
      };
    }
    return { productId, params };
  });

const view = await createFlowView(flow, { productPurchaseParams });
```

```typescript showLineNumbers
import { adapty, createPaywallView } from '@adapty/capacitor';

const view = await createPaywallView(paywall);

view.setEventHandlers({
  onUrlPress(url) {
    window.open(url, '_blank');
    return false;
  },
});

try {
  await view.present();
} catch (error) {
  // handle the error
}
```

h2-use-developer-defined-timer-p0d6fef30.translation:
## Utiliser un minuteur défini par le développeur \{#use-developer-defined-timer\}

Pour utiliser des minuteurs définis par le développeur dans votre application mobile, utilisez le `timerId`, dans cet exemple `CUSTOM_TIMER_NY`, le **Timer ID** du minuteur défini par le développeur que vous avez configuré dans l'Adapty dashboard. Cela permet à votre application de mettre à jour dynamiquement le minuteur avec la valeur correcte — par exemple `13d 09h 03m 34s` (calculée comme l'heure de fin du minuteur, telle que le Jour de l'An, moins l'heure actuelle).

```typescript showLineNumbers
const customTimers = { 'CUSTOM_TIMER_NY': new Date(2025, 0, 1) };

const view = await createPaywallView(paywall, { customTimers });
```

